import Container from './Container';
import SectionHead from './SectionHead';

// Decorative stand-in for the buyer's QR code (a real one is generated by the API)
const QR_CELLS = (() => {
    let seed = 7;
    const rnd = () => {
        seed = (seed * 16807) % 2147483647;
        return seed / 2147483647;
    };
    const isFinder = (x: number, y: number) => (x < 8 && y < 8) || (x > 16 && y < 8) || (x < 8 && y > 16);
    const cells: [number, number][] = [];
    for (let y = 0; y < 25; y++) for (let x = 0; x < 25; x++) if (!isFinder(x, y) && rnd() > 0.52) cells.push([x, y]);
    return cells;
})();

function QrMock() {
    return (
        <svg viewBox="0 0 25 25" shapeRendering="crispEdges" className="block h-auto w-full max-w-[170px]">
            <g fill="#0C1A14">
                {QR_CELLS.map(([x, y]) => (
                    <rect key={`${x}-${y}`} x={x} y={y} width="1" height="1" />
                ))}
                {[[0, 0], [18, 0], [0, 18]].map(([x, y]) => (
                    <g key={`${x}-${y}`}>
                        <rect x={x} y={y} width="7" height="7" />
                        <rect x={x + 1} y={y + 1} width="5" height="5" fill="#E8FAEE" />
                        <rect x={x + 2} y={y + 2} width="3" height="3" />
                    </g>
                ))}
            </g>
        </svg>
    );
}

